package com.academix.service;
import jakarta.persistence.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor public class DashboardService {
 private final EntityManager em;
 @Transactional(readOnly=true) public Map<String,Object> stats(){Map<String,Object> x=new LinkedHashMap<>();x.put("totalStudents",scalar("select count(*) from students"));x.put("activeStudents",scalar("select count(*) from students where status='ACTIVE'"));x.put("inactiveStudents",scalar("select count(*) from students where status<>'ACTIVE'"));x.put("totalCourses",scalar("select count(distinct course) from students where course is not null"));x.put("totalBatches",scalar("select count(distinct batch) from students where batch is not null"));x.put("totalImports",scalar("select count(*) from import_jobs"));x.put("courses",rows("select coalesce(course,'Others'),count(*) from students group by course order by count(*) desc limit 6"));x.put("cities",rows("select coalesce(city,'Others'),count(*) from students group by city order by count(*) desc limit 7"));x.put("recentImports",rows("select file_name,status,total_rows,started_at from import_jobs order by started_at desc limit 5"));return x;}
 private Object scalar(String sql){return em.createNativeQuery(sql).getSingleResult();} private List<?> rows(String sql){return em.createNativeQuery(sql).getResultList();}
}
